import {today,dayFor,totals,shiftDate,round,nextSession} from './model.js';
import {ensureDay,assertUnchanged} from './body.js';
import {healthInsights,prepareHealthProposal} from './health-intelligence.js';
import {normalizeAIResponse} from './ai-checkin.js';
import {createLifeState,factOfDay,buildCleanupPreview,classifyEmail} from './life-model.js';
import {readChatGPTLink,saveChatGPTLink} from './chatgpt-link.js';
const NUTRIENTS=['kcal','protein','carbs','fat'];

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>v==null?'—':Number(v).toLocaleString('en-GB',{maximumFractionDigits:1});
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const uuid=()=>crypto.randomUUID();
const arrow='<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg>';
const btn=(label,action,extra='',secondary=false)=>`<button type="button" class="btn ${secondary?'secondary':''}" data-life="${action}" ${extra}>${esc(label)}</button>`;
const known=(value,suffix='')=>value==null?'Not logged':num(value)+suffix;

export function createLifeUI(ctx){
 const {store,state,render,openSheet,closeSheet,toast,wireForm,saveFooter,navigate,dateControls,nutritionHero,activity,trainingNotice,foodForm}=ctx;
 const life={data:createLifeState(),version:0,loaded:false,error:'',status:null,emails:[],syncing:false,busy:false,filter:'all',cleanupQuery:'',cleanup:null,chat:[],draft:'',proposal:null,aiBusy:false,aiError:'',pendingActions:[],notifications:false,lastSync:0};
 async function api(path,options={}){
  if(!navigator.onLine)throw Error(options.method&&options.method!=='GET'?'Offline. Nothing was saved or sent. Your input has been kept.':'Offline. Reconnect to load your private records.');
  let response;try{response=await fetch('/api/'+path,{credentials:'same-origin',cache:'no-store',...options,headers:{'Content-Type':'application/json',...(options.headers||{})},signal:AbortSignal.timeout(path==='assistant'?60000:45000)});}catch{throw Error('Connection unavailable. Your input has been kept.');}
  let result;try{result=await response.json();}catch{throw Error('This feature needs the Cam’s Life service. Health history is still available.');}
  if(!response.ok){const error=Error(result.message||result.error||'The request could not be completed.');error.code=result.code;throw error;}return result;
 }
 const post=(path,body)=>api(path,{method:'POST',body:JSON.stringify(body)});
 async function load(){
  const results=await Promise.allSettled([api('status'),api('life')]);
  if(results[0].status==='fulfilled')life.status={...results[0].value,gmailConnected:results[0].value.gmailConnected??results[0].value.inboxConnected,hourlyEnabled:results[0].value.hourlyEnabled??results[0].value.hourlySync};
  if(results[1].status==='fulfilled'){life.data=results[1].value.state;life.version=results[1].value.version;life.loaded=true;life.error='';life.emails=(life.data.emails||[]).map(e=>({...e,...classifyEmail(e)}));}
  else life.error=results[1].reason.message;
  if(!document.querySelector('#sheet').open)render();
 }
 async function save(mutate){
  if(life.busy)throw Error('A save is already in progress.');if(!life.loaded)throw Error(life.error||'Private storage is connecting. Try again shortly.');
  life.busy=true;const next=structuredClone(life.data);
  try{mutate(next);const result=await api('life',{method:'PUT',body:JSON.stringify({state:next,version:life.version})});life.data=result.state;life.version=result.version;life.error='';render();}
  catch(e){life.error=e.message;if(/changed|conflict/i.test(e.message))await load();throw e;}finally{life.busy=false;}
 }
 function empty(title,copy,action=''){return `<div class="empty"><h3>${esc(title)}</h3><p>${esc(copy)}</p>${action}</div>`;}
 function notice(){return life.error?`<div class="notice warning" role="status"><div><b>Life sync needs attention</b><p>${esc(life.error)}</p></div>${btn('Retry','reload','',true)}</div>`:'';}
 function factCard(compact=false){const fact=factOfDay(state.date),saved=life.data.favorites.includes(fact.id);return `<article class="fact-card ${compact?'compact':''}"><div class="card-kicker"><span class="eyebrow">FACT OF THE DAY</span></div><h2>${esc(fact.title)}</h2><p>${esc(fact.text||fact.body)}</p><div class="fact-footer"><a href="${esc(fact.sourceURL||fact.sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(fact.source||fact.sourceTitle||'Read the source')} ${arrow}</a><button class="textbtn" data-life="favorite" data-id="${esc(fact.id)}" aria-pressed="${saved}">${saved?'Saved ✓':'Save fact'}</button></div></article>`;}
 function taskRows(limit){const tasks=life.data.tasks.filter(t=>t.status!=='done').slice(0,limit??100);return tasks.length?tasks.map(t=>`<div class="task-row"><button class="task-check" data-life="task-toggle" data-id="${esc(t.id)}" aria-label="Complete ${esc(t.title)}">✓</button><div><b>${esc(t.title)}</b><small>${t.dueDate?dateLabel(t.dueDate):t.dueAt?esc(t.dueAt):'No deadline'}${t.source==='email'?' · From your inbox':''}</small></div>${t.sourceEmailId?`<a href="https://mail.google.com/mail/u/0/#all/${encodeURIComponent(t.sourceEmailId)}" target="_blank" rel="noopener noreferrer" aria-label="Open source email">${arrow}</a>`:''}</div>`).join(''):empty('No open to-dos','Add a to-do or scan Gmail for actions.');}
 function privateUnavailable(){return empty('Private records unavailable',navigator.onLine?'Reconnect private storage to load your to-dos and deliveries.':'Reconnect to load your to-dos and deliveries. Nothing is shown as completed or cleared.');}
 function deliveryCard(d){const done=['picked_up','delivered','cancelled'].includes(d.status);const statusLabel=d.status==='picked_up'?'Picked up':d.status==='delivered'?'Delivered':d.status==='cancelled'?'Cancelled':d.status==='ready_for_pickup'?'Ready to collect':d.status==='in_transit'?'On the way':d.status==='ordered'?'Ordered':'Expected';return `<article class="delivery-card ${done?'complete':''}"><div class="card-kicker"><span class="eyebrow">${esc(d.carrier||d.sender||'Delivery')}</span><span class="tag ${done?'green':''}">${esc(statusLabel)}</span></div><h3>${esc(d.title||d.name||'Your package')}</h3><p>${esc(d.location||d.pickupLocation||d.trackingNumber||'Details from your delivery email')}</p>${d.pickupCode?`<div class="pickup-code"><span>PICKUP CODE</span><button class="pickup-code-value" data-life="copy-code" data-code="${esc(d.pickupCode)}" title="Copy pickup code">${esc(d.pickupCode)}</button></div>`:''}<div class="delivery-footer"><span>${d.deadline||d.pickupDeadline?'Collect by '+esc(d.deadline||d.pickupDeadline):d.expectedDate?'Expected '+esc(d.expectedDate):'No date confirmed'}</span>${btn(done?'Undo':'Picked up ✓','delivery-toggle',`data-id="${esc(d.id)}"`,true)}</div></article>`;}
 function overview(){
  const d=dayFor(store.data,state.date),t=totals(d),p=store.data.profile.targets,hasFood=d.food.length>0;
  const pending=life.loaded?life.data.tasks.filter(t=>t.status!=='done').length:null,packages=life.loaded?life.data.deliveries.filter(d=>!['picked_up','delivered','cancelled'].includes(d.status)).length:null;
  const progress=p.kcal&&hasFood?Math.max(0,Math.min(100,t.kcal/p.kcal*100)):0;
  const recent=Object.keys(store.data.days).filter(date=>date<state.date&&store.data.days[date].food.length).sort().at(-1);
  const remaining=hasFood&&p.kcal!=null&&!t.missing.kcal?p.kcal-t.kcal:null;
  return `<div class="today-greeting"><div><h1>Your day</h1></div>${btn('Check in','ask')}</div>${dateControls()}${notice()}
   <section class="day-fuel"><div class="card-kicker"><span class="eyebrow">FOOD LOG</span><span class="tag">${hasFood?t.pending?'Partial nutrition':t.estimated?'Includes estimates':'Logged today':'Not logged'}</span></div>
    <div class="fuel-main"><div><span class="caption">Calories logged</span><strong>${hasFood?num(t.kcal):'—'}<small>kcal${t.missing.kcal?' + ?':''}</small></strong><p>${remaining!=null?num(Math.abs(remaining))+' kcal '+(remaining<0?'above target':'to target'):hasFood?'Known subtotal':'No food logged yet'}</p></div></div>
    <div class="fuel-bar" role="img" aria-label="${hasFood?Math.round(progress)+'% of calorie target logged':'No food logged'}"><i style="width:${progress}%"></i></div>
    <div class="fuel-footer"><span>${p.kcal?num(p.kcal)+' kcal daily target':'No calorie target set'}</span><button class="textbtn" data-act="food-log">Log a meal ${arrow}</button></div></section>
   ${activity(d)}${!hasFood&&recent?`<button class="last-log" data-date="${recent}"><span><b>Last food log</b><small>${dateLabel(recent)} · ${num(totals(dayFor(store.data,recent)).kcal)} kcal logged</small></span>${arrow}</button>`:''}
   <div class="life-overview">${[['Open to-dos',pending,'Things to do'],['On the way',packages,'Packages expected']].map(([label,value,sub])=>`<button class="life-metric" data-view="life"><span class="eyebrow">${label}</span><strong>${num(value)}</strong><small>${sub}${arrow}</small></button>`).join('')}</div>
   <section class="life-section"><div class="section-head"><h2>To-dos</h2><button class="textbtn" data-view="life">View all ${arrow}</button></div><div class="life-card task-preview">${life.loaded?taskRows(3):privateUnavailable()}<div class="card-bottom">${btn('Add a to-do','task-add','',true)}${btn('Scan Gmail','inbox-sync','',true)}</div></div></section>
   ${packages?`<section class="life-section"><div class="section-head"><h2>Expected deliveries</h2></div>${life.data.deliveries.filter(d=>!['picked_up','delivered','cancelled'].includes(d.status)).slice(0,2).map(deliveryCard).join('')}</section>`:''}
   <section class="life-card next-session"><span class="eyebrow">NEXT SESSION</span><button data-view="training"><span><b>${esc(nextSession(store.data,state.date)?.name||'No session set')}</b><small>${d.workouts.length?d.workouts.map(w=>esc(w.name)).join(', ')+' logged':'Your prescribed session'}</small></span>${arrow}</button></section>${factCard(true)}`;
 }
 function healthTabs(){return `<nav class="health-tabs" aria-label="Health sections">${[['nutrition','Food & activity'],['training','Training'],['body','Body'],['insights','Trends & insights']].map(([view,label])=>`<button data-view="${view}" class="${state.view===view?'active':''}" ${state.view===view?'aria-current="page"':''}>${label}</button>`).join('')}<button data-life="wellbeing">Check in</button></nav>`;}
 function wellbeingCard(){const d=dayFor(store.data,state.date),w=d.wellbeing||{};return `<section class="life-card"><div class="section-head"><h2>Daily check-in</h2>${btn('Check in','wellbeing','',true)}</div><div class="wellbeing-grid"><div><span>Mood</span><b>${w.mood?['','Low','Flat','Okay','Good','Great'][w.mood]:'—'}</b></div><div><span>Energy</span><b>${w.energy?num(w.energy)+' / 5':'—'}</b></div><div><span>Sleep</span><b>${known(w.sleepHours,' h')}</b></div><div><span>Muscle</span><b>${known(d.body?.skeletalMuscleKg,' kg')}</b></div></div>${w.feelings?`<p>${esc(w.feelings)}</p>`:''}</section>`;}
 function simpleChart(series,label,unit){if(!series.length)return empty('No '+label.toLowerCase()+' readings yet.','Only real check-ins appear here.');const values=series.map(p=>p.value),min=Math.min(...values),max=Math.max(...values),span=max-min||1,points=series.map((p,i)=>`${20+(series.length===1?.5:(Date.parse(p.date)-Date.parse(series[0].date))/(Date.parse(series.at(-1).date)-Date.parse(series[0].date)))*620},${160-(p.value-min)/span*120}`);return `<figure class="life-chart"><svg viewBox="0 0 660 200" role="img" aria-label="${esc(label)} from ${esc(series[0].date)} to ${esc(series.at(-1).date)}"><line x1="20" y1="160" x2="640" y2="160" stroke="var(--border)"/><polyline points="${points.join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>${series.map((p,i)=>`<circle cx="${points[i].split(',')[0]}" cy="${points[i].split(',')[1]}" r="4" fill="var(--accent)"><title>${p.date}: ${p.value} ${unit}</title></circle>`).join('')}</svg><figcaption><span>${dateLabel(series[0].date)} · ${num(series[0].value)} ${unit}</span><span>${dateLabel(series.at(-1).date)} · ${num(series.at(-1).value)} ${unit}</span></figcaption><details><summary>View recorded values</summary><table><thead><tr><th>Date</th><th>${esc(label)}</th></tr></thead><tbody>${series.map(p=>`<tr><td>${p.date}</td><td>${num(p.value)} ${unit}</td></tr>`).join('')}</tbody></table></details></figure>`;}
 function insights(){const days=Object.entries(store.data.days).filter(([d])=>d<=state.date&&d>=shiftDate(state.date,-29)).sort(([a],[b])=>a.localeCompare(b)),weight=days.filter(([,d])=>d.weightKg!=null).map(([date,d])=>({date,value:d.weightKg})),muscle=days.filter(([,d])=>d.body?.skeletalMuscleKg!=null).map(([date,d])=>({date,value:d.body.skeletalMuscleKg})),ins=healthInsights(store.data,state.date);const entries=Array.isArray(ins)?ins:ins.insights||ins.cards||[];return `${dateControls()}<div class="page-intro"><div><span class="eyebrow">THE BIGGER PICTURE</span><h1>Trends & insights</h1><p>Recorded values, your chosen targets, and honest gaps.</p></div>${btn('Ask about my progress','ask')}</div><div class="life-grid"><section class="life-card"><div class="section-head"><h2>Weight · last 30 days</h2><span class="tag">${weight.length} readings</span></div>${simpleChart(weight,'Weight','kg')}<div class="section-head"><h2>Skeletal muscle</h2><span class="tag">WATCH / SCALE</span></div>${simpleChart(muscle,'Muscle','kg')}</section><section class="life-card"><span class="eyebrow">RESULTS & EXPECTATIONS</span><h2>What your logs can tell us</h2>${entries.length?entries.map(i=>`<article class="insight-item"><h3>${esc(i.title||i.label||'Your trend')}</h3><p>${esc(i.text||i.detail||i.message||i.description)}</p></article>`).join(''):`<p>${esc(ins.summary||'More consistent check-ins will make patterns clearer. A partial food log is not a full day’s intake.')}</p>`}${ins.weightTrend?.projection?`<article class="insight-item"><h3>Two-week projection · estimate</h3><p>${num(ins.weightTrend.projection.value)} kg around ${dateLabel(ins.weightTrend.projection.date)} if the recent observed trend continues.</p></article>`:''}<p class="help">Trends describe logs. Forecasts need enough dated readings, and are estimates rather than promises.</p>${btn('Ask about these trends','ask','',true)}</section></div>${wellbeingCard()}`;}
 function inbox(){const digest=life.data.lastDigest,shown=life.emails.filter(e=>life.filter==='all'||e.category===life.filter||life.filter==='unread'&&e.unread);return `<div class="page-intro"><div><span class="eyebrow">YOUR ATTENTION, BACK</span><h1>Inbox</h1><p>Unread mail, actions and delivery updates.</p></div>${btn(life.syncing?'Scanning…':'Scan Gmail','inbox-sync',life.syncing?'disabled':'')}</div>${notice()}<div class="inbox-toolbar"><div class="segmented">${[['all','All'],['unread','Unread'],['action','Needs you'],['noise','Noise']].map(([key,label])=>`<button data-life="inbox-filter" data-filter="${key}" class="${life.filter===key?'selected':''}">${label}</button>`).join('')}</div><div>${btn(life.status?.gmailConnected?'Gmail connected':'Connect Gmail','gmail-connect','',true)}${btn('Notifications','notifications','',true)}</div></div><div class="life-grid"><section><div class="life-card inbox-digest"><span class="eyebrow">YOUR LATEST BRIEF</span><h2>${digest?'Latest summary':'No summary yet'}</h2><p>${esc(digest?.summary||(digest?`${digest.total} messages reviewed. ${digest.counts.action} need attention, ${digest.counts.noise} look like noise.`:null)||'Scan your mailbox to collect action items, delivery updates, and a short digest.')}</p>${digest?.generatedAt?`<small>Updated ${esc(new Date(digest.generatedAt).toLocaleString('en-GB'))}</small>`:''}<p class="help">${life.status?.hourlyEnabled?'Hourly summaries are enabled.':'This mailbox view updates when you scan Gmail.'}</p></div><div class="section-head"><h2>Mail to review</h2><span>${shown.length} loaded</span></div><div class="life-card inbox-list">${shown.length?shown.map(e=>`<a class="inbox-row ${e.unread?'unread':''}" href="https://mail.google.com/mail/u/0/#all/${encodeURIComponent(e.id)}" target="_blank" rel="noopener noreferrer"><span class="mail-avatar">${esc((e.fromName||e.from||'?')[0].toUpperCase())}</span><div><b>${esc(e.subject||'(No subject)')}</b><span>${esc(e.fromName||e.from)}</span><p>${esc(e.snippet||'')}</p></div><small>${esc(e.category||'update')} ${arrow}</small></a>`).join(''):empty('No mail loaded yet.','Connect Gmail, then scan. Your mailbox stays in Gmail.')}</div></section><section class="life-card cleanup-card"><span class="eyebrow">LET IT GO</span><h2>Mailbox cleanup</h2><form id="cleanup-form"><label class="field">What can go?<textarea name="query" rows="3" maxlength="400" placeholder="Delete unread Codex auto-review notifications">${esc(life.cleanupQuery)}</textarea></label><div class="cleanup-examples">${['Codex auto review','Newsletters','GitHub notifications'].map(q=>`<button type="button" class="tag" data-life="cleanup-example" data-query="${q}">${q}</button>`).join('')}</div><button class="btn full" type="submit">Find matches to review</button></form><p class="help">You review the exact messages first. Trash is recoverable in Gmail for 30 days; nothing is permanently deleted here.</p>${life.status?.gmailConnected?btn('Disconnect Gmail','gmail-disconnect','',true):''}</section></div>`;}
 function lifeView(){if(!life.loaded)return `<div class="page-intro"><div><h1>Life</h1><p>To-dos, packages and pickup codes.</p></div></div>${notice()}<section class="life-card">${privateUnavailable()}</section>${factCard()}`;const done=life.data.tasks.filter(t=>t.status==='done'),deliveries=life.data.deliveries;return `<div class="page-intro"><div><span class="eyebrow">MAKE SPACE</span><h1>Life</h1><p>To-dos, packages and pickup codes.</p></div>${btn('Add a to-do','task-add')}</div>${notice()}<div class="life-grid"><section><div class="section-head"><h2>Your to-do list</h2><span class="tag">${life.data.tasks.length-done.length} open</span></div><div class="life-card">${taskRows()}${done.length?`<details class="completed-tasks"><summary>${done.length} completed</summary>${done.map(t=>`<div class="task-row complete"><button class="task-check" data-life="task-toggle" data-id="${esc(t.id)}" aria-label="Reopen ${esc(t.title)}">✓</button><b>${esc(t.title)}</b></div>`).join('')}</details>`:''}</div><div class="section-head"><h2>Deliveries & pickup</h2>${btn('Add package','delivery-add','',true)}</div><div class="delivery-list">${deliveries.length?deliveries.map(deliveryCard).join(''):`<div class="life-card">${empty('Nothing on the way yet.','Scan Gmail to discover delivery emails, or add a package yourself.',btn('Scan Gmail','inbox-sync','',true))}</div>`}</div></section><section>${factCard()}<div class="life-card"><span class="eyebrow">YOUR COLLECTION</span><h3>${life.data.favorites.length} saved facts</h3><p>Save the facts you want to come back to.</p>${btn('View saved facts','saved-facts','',true)}</div></section></div>`;}
 function aiStatus(){const setup=life.status?.aiSetup;return life.status?.aiConfigured?`<span class="ai-connection"><i aria-hidden="true"></i>GPT-OSS 120B · connected</span>${Number.isFinite(setup?.remainingToday)?`<small>${setup.remainingToday} / ${setup.dailyLimit} requests left today</small>`:''}`:`<span class="ai-connection">AI is not connected yet</span>`;}
 function proposalReview(){
  const proposal=life.proposal;if(!proposal)return '';
  const foods=proposal.changes.filter(c=>c.kind==='append'&&c.path.at(-1)==='food'),workouts=proposal.changes.filter(c=>c.kind==='append'&&c.path.at(-1)==='workouts'),metrics=proposal.changes.filter(c=>!c.kind);
  return `<section class="ai-proposal" aria-label="Check-in review"><div class="section-head"><h2>Your check-in</h2><span>${esc(dateLabel(proposal.date))}</span></div>${foods.map(c=>{const food=c.after;return `<article class="ai-food"><div class="card-kicker"><h3>${esc(food.name)}</h3><span class="tag">${NUTRIENTS.some(key=>food[key]!=null)?food.estimated?'AI estimate':'Provided values':'Nutrition unknown'}</span></div><p class="ai-portion">${esc(food.quantity||'Portion not specified')}</p>${nutrientRow(food)}${food.note?`<p class="help preserve">${esc(food.note)}</p>`:''}${food.source?`<small class="ai-source">${esc(food.source)}</small>`:''}${food.reviewRequired?'<p class="help">Calories and macros need a second look. The estimate is kept for you to review.</p>':''}</article>`;}).join('')}${workouts.map(c=>`<article class="ai-workout"><h3>${esc(c.after.name)}</h3><p>${c.after.status==='completed'?'Completed':'Partial'} · ${c.after.durationMin==null?'Duration not logged':num(c.after.durationMin)+' min'}</p>${c.after.notes?`<p class="help">${esc(c.after.notes)}</p>`:''}</article>`).join('')}${metrics.length?`<dl class="ai-metrics">${metrics.map(c=>`<div><dt>${esc(c.label||c.path.at(-1))}</dt><dd>${esc(c.after==null?'Unknown':typeof c.after==='number'?num(c.after):c.after)}</dd></div>`).join('')}</dl>`:''}<p class="help">Check the estimate or tell me what to change. Saving adds these entries to your diary${metrics.length?' and updates the readings shown above':''}.</p><p class="help ai-public-note">Your health diary is saved in your existing public GitHub repository.</p><div class="ai-review-actions">${btn(life.busy?'Saving…':'Save to diary','proposal-save',life.busy||life.aiBusy?'disabled':'')}${btn('Discard draft','proposal-dismiss',life.busy||life.aiBusy?'disabled':'',true)}</div></section>`;
 }
 function ask(){return `<div class="page-intro"><div><span class="eyebrow">YOUR WORDS → YOUR LIFE</span><h1>Ask</h1><p>Meals, watch readings and your progress.</p></div></div><div class="ai-status-line">${aiStatus()}${!life.status?.aiConfigured?btn('Connect AI','ai-setup','',true):''}</div><div class="assistant-layout"><section class="assistant-main life-card"><div class="chat-stream" aria-live="polite" aria-busy="${life.aiBusy||life.busy}">${life.chat.length?life.chat.map(m=>`<article class="chat-bubble ${m.role}"><span>${m.role==='user'?'YOU':m.error?'NEEDS ATTENTION':'CAM’S LIFE · AI'}</span><p>${esc(m.text)}</p></article>`).join(''):`<div class="assistant-welcome"><h2>Tell me about your day.</h2><p>Describe what you ate in your own words. AI fills a meal card with calories, macros and its assumptions.</p><p class="help">${life.status?.aiConfigured?'You can also share your weight, steps or watch readings, and ask about trends in your logs.':'Connect your free Groq account once to start.'}</p></div>`}${life.aiBusy?'<div class="chat-bubble assistant ai-thinking"><span>CAM’S LIFE · AI</span><p>Working through your check-in<span aria-hidden="true">…</span></p></div>':life.busy?'<div class="chat-bubble assistant"><span>CAM’S LIFE</span><p>Saving and verifying your diary…</p></div>':''}${proposalReview()}</div><form class="composer" id="assistant-form"><label class="sr-only" for="assistant-message">Your check-in</label><textarea id="assistant-message" name="message" rows="3" maxlength="3000" placeholder="I ate… My watch says… Today I feel…">${esc(life.draft)}</textarea><div class="composer-actions"><small>GPT-OSS 120B on Groq · text only</small><button class="btn" type="submit" ${life.busy||life.aiBusy?'disabled':''}>${life.aiBusy?'Thinking…':'Send'} ${arrow}</button></div><p class="help ai-context-note">Your message and relevant health logs are sent to Groq. Photos are not supported by this model.</p></form></section><aside class="assistant-aside"><div class="life-card"><span class="eyebrow">ONE CONVERSATION</span><h3>Start anywhere</h3><div class="prompt-chips">${[['Log my food','I ate '],['Watch check-in','My watch says '],['Review my progress','What trends can you see in my recent logs?'],['How I feel','Today I feel ']].map(([label,prompt])=>`<button data-life="prompt" data-prompt="${esc(prompt)}" ${life.aiBusy?'disabled':''}>${label} ${arrow}</button>`).join('')}</div><p class="help">Missing portions stay unknown until you tell me. AI estimates stay labelled, and you review each check-in before saving.</p></div>${wellbeingCard()}</aside></div>`;}
 function setupBlock(){return `<section class="life-card"><span class="eyebrow">YOUR CONNECTIONS</span><h2>Connections</h2><div class="setup-grid"><div><b>AI · GPT-OSS 120B on Groq</b><p>${life.status?.aiConfigured?'Connected. Describe a meal or a check-in in Ask, then review and save it here.':'Connect a free Groq account so a real AI model can fill your meals and interpret check-ins inside Cam’s Life.'}</p><div class="ai-status-line">${aiStatus()}</div><div class="connection-actions">${btn(life.status?.aiConfigured?'Change AI key':'Connect AI','ai-setup','',true)}${life.status?.aiConfigured?btn('Test connection','ai-test','',true)+btn('Disconnect AI','ai-disconnect','',true):''}</div><p class="help">Keep Groq on its Free plan. If a limit is reached, the request stops; Cam’s Life never switches to a paid fallback.</p>${life.aiError?`<p class="form-error" role="alert">${esc(life.aiError)}</p>`:''}</div><div><b>Gmail</b><p>${life.status?.gmailConnected?`Connected${life.status.email?' as '+esc(life.status.email):''}. Scan for actions and deliveries.`:life.status?.gmail?'Google sign-in is ready. Connect your account to allow mailbox access.':'One-time Google app setup is needed. Start here for the steps and secure JSON import.'}</p>${btn(life.status?.gmailConnected?'Scan Gmail':life.status?.gmail?'Connect Gmail':'Set up Gmail',life.status?.gmailConnected?'inbox-sync':'gmail-connect','',true)}${life.status?.gmailConnected?btn('Disconnect Gmail','gmail-disconnect','',true):''}</div></div></section>`;}
 function aiSetupForm(){
  const setup=life.status?.aiSetup,ready=setup?.storageReady&&setup?.encryptionReady;
  openSheet('Connect AI',`<div class="ai-setup"><p>Use GPT-OSS 120B inside Cam’s Life with Groq’s free API plan.</p><ol><li><a href="https://console.groq.com/keys" target="_blank" rel="noopener noreferrer">Open Groq and create an API key</a>. Create a free account if you need one.</li><li>Keep the account on <b>Free</b>. A key from an account you upgrade to a paid plan can incur Groq charges.</li><li>Enter the key below. Cam’s Life tests the model, then encrypts your key in private server storage.</li></ol>${ready?`<form id="ai-setup-form" autocomplete="off"><label class="field">Groq API key<input id="groq-key" name="apiKey" type="password" required maxlength="250" autocomplete="off" spellcheck="false" autocapitalize="off" placeholder="gsk_…"></label><p class="help">Enter the key only in this field. It stays out of chat, GitHub and browser storage.</p><p class="form-error" id="ai-setup-error" role="alert"></p><button class="btn full" type="submit">Connect & test AI</button></form>`:`<div class="notice warning"><p>${setup?.storageReady?'Private encryption is unavailable. Restore the app service before adding a key.':'Private storage is unavailable. Reconnect the app service before adding a key.'}</p></div>${btn('Retry connection status','ai-setup','',true)}`}<p class="help">50 requests a day in Cam’s Life, with no automatic retries or model fallback. Groq’s own limits also apply.</p></div>`,()=>{
   const form=document.querySelector('#ai-setup-form');if(!form)return;
   const input=form.querySelector('#groq-key'),button=form.querySelector('[type=submit]'),error=form.querySelector('#ai-setup-error');let busy=false;
   form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;let apiKey=input.value.trim();input.value='';if(!apiKey){error.textContent='Enter your Groq API key.';return;}busy=true;button.disabled=true;input.disabled=true;button.textContent='Testing GPT-OSS 120B…';error.textContent='';
    try{await post('ai/setup',{apiKey});apiKey='';life.status=await api('status');life.aiError='';closeSheet(true);render();toast('AI connected. Your model answered successfully.');}
    catch(e){apiKey='';error.textContent=e.message;}
    finally{busy=false;button.disabled=false;input.disabled=false;button.textContent='Connect & test AI';}
   });
  });
 }
 function gmailSetupForm(){
  const setup=life.status?.gmailSetup,redirect=setup?.redirectUri||location.origin+'/api/inbox/callback';
  const ready=setup?.storageReady&&setup?.encryptionReady;
  openSheet('Set up Gmail',`<div class="gmail-setup"><p>Register Cam’s Life once with Google, then sign in to your mailbox. The Gmail API has no usage charge.</p><ol><li><a href="https://console.cloud.google.com/projectcreate" target="_blank" rel="noopener noreferrer">Create a Google Cloud project</a> named <b>Cam’s Life</b>. You do not need a billing account for Gmail.</li><li>Open <b>APIs & Services → Library</b>. Find <b>Gmail API</b> and enable it.</li><li>Open <b>Google Auth Platform</b>. Set the app name and your email under <b>Branding</b>. Under <b>Audience</b>, choose <b>External</b>, keep <b>Testing</b>, and add your Gmail address as a test user. Under <b>Data Access</b>, add <code>https://www.googleapis.com/auth/gmail.modify</code>.</li><li>Under <b>Clients → Create client</b>, choose <b>Web application</b>, even on your phone. Add the exact address below under <b>Authorized redirect URIs</b>, then create the client and download its JSON.</li></ol><label class="field">Google redirect address<input id="gmail-redirect" readonly value="${esc(redirect)}"></label>${btn('Copy redirect address','gmail-copy-redirect','',true)}<p class="help">Testing access expires after seven days, so Google may ask you to reconnect. Keep this personal app in testing while setting it up.</p>${ready?`<form id="gmail-setup-form" autocomplete="off"><label class="field">Import Google client JSON<input id="gmail-client-json" type="file" accept=".json,application/json" required></label><p class="help">Import directly here. The client settings are encrypted in private server storage. They are never added to GitHub or saved on this device.</p><p class="form-error" id="gmail-setup-error" role="alert"></p><button class="btn full" type="submit" disabled>Save Google setup</button></form>`:`<div class="notice warning"><p>${setup?.storageReady?'Mailbox encryption is unavailable. The app owner needs to restore it before setup can be saved.':'Private storage is unavailable. Reconnect the app service before importing your Google setup.'}</p></div>${btn('Retry connection status','gmail-connect','',true)}`}</div>`,()=>{
   const form=document.querySelector('#gmail-setup-form');if(!form)return;
   const error=form.querySelector('#gmail-setup-error'),submit=form.querySelector('[type=submit]'),fileInput=form.querySelector('#gmail-client-json');let imported=null,loading=false,generation=0;
   fileInput.addEventListener('change',async()=>{
    const current=++generation;imported=null;submit.disabled=true;error.textContent='';const file=fileInput.files[0];if(!file)return;
    try{if(file.size>32768)throw Error('Choose the small client JSON downloaded from Google, under 32 KB.');
     const payload=JSON.parse(await file.text()),web=payload.web;if(current!==generation)return;
     if(!web||typeof web.client_id!=='string'||typeof web.client_secret!=='string')throw Error('Choose a Web application client JSON. Android, Desktop and service-account files cannot connect this app.');
     if(!Array.isArray(web.redirect_uris)||!web.redirect_uris.includes(redirect))throw Error('The JSON is missing this app’s redirect address. Add it in Google Clients and download the JSON again.');
     imported={clientId:web.client_id,clientSecret:web.client_secret,redirectUris:web.redirect_uris};submit.disabled=false;error.textContent='Ready to save. Mailbox access is granted in the next Google sign-in step.';
    }catch(e){if(current===generation)error.textContent=e instanceof SyntaxError?'This file is not valid Google client JSON. Download it again from Google Clients.':e.message;}
   });
   form.addEventListener('submit',async e=>{e.preventDefault();if(!imported||loading)return;loading=true;submit.disabled=true;fileInput.disabled=true;error.textContent='';
    try{await post('inbox/setup',imported);imported=null;form.reset();life.status=await api('status');closeSheet(true);render();toast('Google setup saved. Tap Connect Gmail to sign in.');}
    catch(e){error.textContent=e.message;}finally{loading=false;submit.disabled=!imported;fileInput.disabled=false;}
   });
  });
 }
 function wellbeingForm(){const date=state.date,d=dayFor(store.data,date),baseline=structuredClone(d.wellbeing),bodyBase=d.body?.skeletalMuscleKg;openSheet('Daily check-in',`<form><p class="help">For ${dateLabel(date)}. Leave unmeasured values blank.</p><div class="form-grid">${[['mood','Mood','Low','Flat','Okay','Good','Great'],['energy','Energy','Very low','Low','Okay','Good','High']].map(([key,label,...values])=>`<label class="field">${label}<select name="${key}"><option value="">Not logged</option>${values.map((v,i)=>`<option value="${i+1}" ${d.wellbeing?.[key]===i+1?'selected':''}>${v}</option>`).join('')}</select></label>`).join('')}<label class="field">Sleep (hours)<input name="sleepHours" type="number" min="0" max="24" step="0.1" value="${d.wellbeing?.sleepHours??''}"></label><label class="field">Skeletal muscle (kg)<input name="skeletalMuscleKg" type="number" min="0.1" max="250" step="0.1" value="${bodyBase??''}" placeholder="From your watch or scale"></label></div><label class="field">Feelings<textarea name="feelings" maxlength="2000">${esc(d.wellbeing?.feelings)}</textarea></label><p class="help">These health entries use your existing public repository. Keep private personal details out of this field.</p>${saveFooter('Save check-in')}</form>`,()=>wireForm(async fd=>store.save(data=>{const day=ensureDay(data,date);assertUnchanged(day.wellbeing,baseline);assertUnchanged(day.body?.skeletalMuscleKg,bodyBase);day.wellbeing={...day.wellbeing,mood:fd.get('mood')?Number(fd.get('mood')):null,energy:fd.get('energy')?Number(fd.get('energy')):null,sleepHours:fd.get('sleepHours')!==''?Number(fd.get('sleepHours')):null,feelings:String(fd.get('feelings'))};if(fd.get('skeletalMuscleKg')!==''||bodyBase!=null)day.body={...day.body,skeletalMuscleKg:fd.get('skeletalMuscleKg')!==''?Number(fd.get('skeletalMuscleKg')):null,recordedAt:new Date().toISOString()};},'Save daily wellbeing and muscle check-in')));}
 function taskForm(){openSheet('Add a to-do',`<form id="life-task-form"><label class="field">To-do<input name="title" required maxlength="300" placeholder="Pick up my package"></label><label class="field">Due date (optional)<input name="dueDate" type="date"></label><p class="form-error" role="alert"></p><button class="btn" type="submit">Add to-do</button></form>`,()=>document.querySelector('#life-task-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await save(s=>s.tasks.push({id:uuid(),title:String(fd.get('title')),dueDate:fd.get('dueDate')||null,status:'open',source:'manual',createdAt:new Date().toISOString()}));closeSheet(true);toast('To-do saved.');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}}));}
 function deliveryForm(){openSheet('Add a delivery',`<form id="life-delivery-form"><label class="field">Package<input name="title" required maxlength="300" placeholder="My order"></label><div class="form-grid">${[['carrier','Carrier'],['trackingNumber','Tracking number'],['pickupCode','Pickup code'],['pickupLocation','Pickup location']].map(([key,label])=>`<label class="field">${label}<input name="${key}" maxlength="200"></label>`).join('')}<label class="field">Collect by<input type="date" name="pickupDeadline"></label></div><p class="form-error" role="alert"></p><button class="btn" type="submit">Save package</button></form>`,()=>document.querySelector('#life-delivery-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.target),b=e.target.querySelector('button');b.disabled=true;try{await save(s=>s.deliveries.push({id:uuid(),...Object.fromEntries([...fd].map(([k,v])=>[k,String(v).trim()||null])),status:fd.get('pickupCode')?'ready_for_pickup':'ordered',createdAt:new Date().toISOString(),source:'manual'}));closeSheet(true);toast('Package saved.');}catch(err){e.target.querySelector('.form-error').textContent=err.message;}finally{b.disabled=false;}}));}
 function chatGPTHandoff(){const prompt=`Help me with Cam’s Life. The repository is CameronNel/Cam-s-Health. Read AGENTS.md and the latest dist/data/health.json through GitHub before logging. Preserve all existing records, validate changes, commit only my actual requested entries, and verify them after saving. My selected date is ${state.date}. ${life.draft||life.lastCheckIn||'Please review my recent health logs, trends, concerns, and next useful check-in.'}\nIf analyzing a photo, I will attach it here. Ask about unknown quantities; never infer body fat from photos.`;const link=readChatGPTLink();openSheet('Continue with your ChatGPT subscription',`<p class="help">Copy your prompt, open ChatGPT, and paste it. This uses ChatGPT separately, with no paid API. Attach your photo there if needed.</p><label class="field">Your prompt<textarea id="handoff-prompt" rows="8" readonly>${esc(prompt)}</textarea></label>${btn('Copy prompt','copy-handoff')}<a class="btn secondary" id="chatgpt-open-link" href="${esc(link)}" target="_blank" rel="noopener noreferrer">Open ChatGPT</a><details class="disclosure"><summary>Use a dedicated Cam’s Life chat</summary><form id="chatgpt-link-form"><label class="field">ChatGPT conversation or project link<input name="url" type="url" maxlength="1000" value="${link==='https://chatgpt.com/'?'':esc(link)}" placeholder="https://chatgpt.com/c/…"></label><p class="help">Paste your own chat or project URL. This preference stays on this device. Leave blank to open ChatGPT home.</p><button type="submit" class="btn secondary">Save chat link</button><p class="form-error" role="alert"></p></form></details><p class="help">ChatGPT needs its GitHub connection to update your health record. Return here and refresh after a verified save. Nothing has been logged or sent by opening this sheet.</p>`,()=>document.querySelector('#chatgpt-link-form').addEventListener('submit',e=>{e.preventDefault();try{const url=saveChatGPTLink(new FormData(e.target).get('url'));document.querySelector('#chatgpt-open-link').href=url;toast('ChatGPT destination saved on this device.');e.target.querySelector('.form-error').textContent='';}catch(err){e.target.querySelector('.form-error').textContent=err.message;}}));}
 async function sync(){if(life.syncing)return;life.syncing=true;render();try{const result=await post('inbox/sync',{});life.emails=(result.state?.emails||result.emails||[]).map(e=>({...e,...classifyEmail(e)}));life.lastSync=Date.now();await load();if(life.notifications&&Notification.permission==='granted')new Notification('Cam’s Life · inbox updated',{body:`${life.data.tasks.filter(t=>t.status!=='done').length} open to-dos. ${life.data.deliveries.filter(d=>d.status==='ready_for_pickup').length} pickups ready.`});toast('Inbox scanned. Deliveries and to-dos updated.');}catch(e){life.error=e.message;toast(e.message);}finally{life.syncing=false;render();}}
 async function cleanup(query){life.cleanupQuery=query;const preview=buildCleanupPreview(life.emails,query),items=preview.emails||preview.messages||preview.matches||preview.candidates||[];const ids=preview.messageIds||preview.ids||items.map(e=>e.id);if(!ids.length){toast(preview.unsupportedReason||preview.message||'No supported matches in the loaded mail. Scan unread mail first.');return;}const chosen=life.emails.filter(e=>ids.includes(e.id));openSheet('Review messages to clear',`<p class="help">${chosen.length} exact messages match “${esc(query)}”. Choose an action, then confirm.</p><div class="cleanup-review">${chosen.map(e=>`<label class="inbox-row"><input type="checkbox" name="cleanup-id" value="${esc(e.id)}" checked><span><b>${esc(e.subject)}</b><small>${esc(e.from)}</small></span></label>`).join('')}</div><label class="field">Action<select id="cleanup-operation"><option value="trash">Move to Trash</option><option value="archive">Archive</option><option value="read">Mark read</option></select></label><p id="cleanup-error" class="form-error" role="alert"></p>${btn('Confirm for selected messages','cleanup-apply')}`);}
 function transportActions(actions){return actions.map(({id,...action})=>action);}
 function normalizeResult(result,health,date,message,conversation=[],pendingActions=[]){return normalizeAIResponse({summary:result.summary,actions:result.actions,questions:result.questions},health,date,{message,conversation,pendingActions});}
 function stableActions(actions,previous){
  const used=new Set(),ids=new Map(),isEntry=action=>['add_food','add_workout'].includes(action.type);
  actions.forEach((action,index)=>{if(!isEntry(action))return;const oldIndex=previous.findIndex((entry,i)=>!used.has(i)&&entry.type===action.type&&entry.name===action.name);if(oldIndex>=0){used.add(oldIndex);ids.set(index,previous[oldIndex].id);}});
  return actions.map((action,index)=>{if(!isEntry(action))return action;let id=ids.get(index);if(!id){const oldIndex=previous.findIndex((entry,i)=>!used.has(i)&&entry.type===action.type);if(oldIndex>=0){used.add(oldIndex);id=previous[oldIndex].id;}}return {...action,id:id||(action.type==='add_food'?'food-':'workout-')+uuid()};});
 }
 function recentConversation(){const result=[];let remaining=1800;for(const entry of life.chat.filter(m=>!m.error).slice(-6).reverse()){if(!remaining)break;const content=entry.text.slice(0,Math.min(1200,remaining));result.unshift({role:entry.role,content});remaining-=content.length;}return result;}
 async function requireAI(){if(!life.status?.aiConfigured)life.status=await api('status');if(!life.status?.aiConfigured)throw Error('Connect AI in Settings first. Your check-in is kept here.');}
 async function estimateFood(description,quantity='',note='',date=state.date){
  if(life.aiBusy||life.busy)throw Error('Wait for the current request to finish.');
  life.aiBusy=true;const health=structuredClone(store.data);
  const message=`Estimate one food entry for my diary. Food: ${String(description).slice(0,300)}\nPortion: ${String(quantity).slice(0,500)||'Not specified'}${note?'\nMy cooking or label notes: '+String(note).slice(0,1500):''}`;
  try{await requireAI();const result=await post('assistant',{message,date,health,conversation:[],pendingActions:[]}),normalized=normalizeResult(result,health,date,message),foods=normalized.actions.filter(a=>a.type==='add_food');if(foods.length!==1)throw Error(normalized.questions.join(' ')||'Describe one food here, or use Ask to review a meal with several foods.');if(!foods[0].quantity.trim()||NUTRIENTS.every(key=>foods[0][key]==null)&&normalized.questions.length)throw Error(normalized.questions.join(' ')||'How much did you eat? Add your portion before asking for an estimate.');life.status=await api('status').catch(()=>life.status);return foods[0];}
  finally{life.aiBusy=false;}
 }
 async function send(form){
  if(life.busy||life.aiBusy)return;
  const message=String(new FormData(form).get('message')||'').trim();if(!message)return;
  life.draft=message;life.lastCheckIn=message;life.aiError='';
  const date=state.date;if(life.proposal&&life.proposal.date!==date){life.chat.push({role:'assistant',text:`Finish or discard your draft for ${dateLabel(life.proposal.date)} before starting a check-in for another date.`,error:true});render();return;}
  const health=structuredClone(store.data),conversation=recentConversation(),previous=life.proposal?life.pendingActions:[],pendingActions=transportActions(previous);
  life.aiBusy=true;render();
  try{
   if(life.proposal){try{life.proposal.apply(structuredClone(health));}catch{throw Error('Your diary changed after this draft was prepared. Your draft is kept; discard it and start again from the updated records.');}}
   await requireAI();life.chat.push({role:'user',text:message});render();
   const result=await post('assistant',{message,date,health,conversation,pendingActions}),normalized=normalizeResult(result,health,date,message,conversation,pendingActions);
   const actions=stableActions(normalized.actions,previous);
   if(actions.length||previous.length){const proposal=prepareHealthProposal(health,date,actions);life.proposal=proposal.changes.length?{...proposal,date}:null;life.pendingActions=life.proposal?actions:[];}
   life.chat.push({role:'assistant',text:[normalized.summary,...normalized.questions].filter(Boolean).join('\n\n')||'There are no new records to save.'});
   if(life.draft===message)life.draft='';life.status=await api('status').catch(()=>life.status);
  }catch(e){life.aiError=e.message;life.chat.push({role:'assistant',text:e.message,error:true});}
  finally{life.aiBusy=false;render();document.querySelector('.ai-proposal')?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(!life.proposal)document.querySelector('.chat-stream')?.scrollTo({top:999999,behavior:'smooth'});}
 }
 function nutrientRow(values,label='Portion nutrition'){return `<div class="meal-nutrients" aria-label="${esc(label)}">${[['kcal','kcal'],['protein','protein'],['carbs','carbs'],['fat','fat']].map(([key,name])=>`<div><b>${num(values?.[key])}${key==='kcal'?'':'<small> g</small>'}</b><span>${name}</span></div>`).join('')}</div>`;}
 async function action(name,b){
  if(['ask','inbox','life'].includes(name)){navigate(name);return true;}
  if(name==='reload'){await load();return true;}if(name==='wellbeing'){wellbeingForm();return true;}if(name==='task-add'){taskForm();return true;}if(name==='delivery-add'){deliveryForm();return true;}
  if(name==='task-toggle'){await save(s=>{const t=s.tasks.find(t=>t.id===b.dataset.id);if(t){t.status=t.status==='done'?'open':'done';t.completedAt=t.status==='done'?new Date().toISOString():null;t.updatedAt=new Date().toISOString();}});return true;}
  if(name==='delivery-toggle'){await save(s=>{const d=s.deliveries.find(d=>d.id===b.dataset.id);if(d){const done=['picked_up','delivered','cancelled'].includes(d.status);const previous=d.status;d.status=done?(d.previousStatus||'unknown'):'picked_up';if(!done)d.previousStatus=previous;d.completedAt=done?null:new Date().toISOString();}});return true;}
  if(name==='favorite'){await save(s=>{const i=s.favorites.indexOf(b.dataset.id);if(i<0)s.favorites.push(b.dataset.id);else s.favorites.splice(i,1);});return true;}
  if(name==='saved-facts'){const facts=Array.from({length:366},(_,i)=>factOfDay(shiftDate(state.date,-i))).filter((f,i,all)=>life.data.favorites.includes(f.id)&&all.findIndex(x=>x.id===f.id)===i);openSheet('Saved curiosities',facts.length?facts.map(f=>`<article class="insight-item"><h3>${esc(f.title)}</h3><p>${esc(f.text||f.body)}</p><a href="${esc(f.sourceURL||f.sourceUrl)}" target="_blank" rel="noopener noreferrer">Read the source ${arrow}</a></article>`).join(''):empty('Your collection starts here.','Save a daily fact to return to it later.'));return true;}
  if(name==='copy-code'){await navigator.clipboard.writeText(b.dataset.code);toast('Pickup code copied.');return true;}
  if(name==='inbox-sync'){await sync();return true;}if(name==='inbox-filter'){life.filter=b.dataset.filter;render();return true;}
  if(name==='gmail-connect'){b.disabled=true;try{life.status=await api('status');if(!life.status.gmail){gmailSetupForm();return true;}const result=await post('inbox/connect',{});const url=new URL(result.url);if(url.origin!=='https://accounts.google.com')throw Error('Unexpected Gmail sign-in address.');location.assign(url.href);return true;}finally{b.disabled=false;}}
  if(name==='gmail-copy-redirect'){await navigator.clipboard.writeText(document.querySelector('#gmail-redirect').value);toast('Google redirect address copied.');return true;}
  if(name==='gmail-disconnect'){await post('inbox/disconnect',{});life.emails=[];await load();toast('Gmail disconnected.');return true;}
  if(name==='notifications'){if(!('Notification' in window))throw Error('This browser does not support notifications.');const permission=await Notification.requestPermission();life.notifications=permission==='granted';toast(life.notifications?'Inbox notifications enabled while this tab is open.':'Notifications were not enabled.');return true;}
  if(name==='cleanup-example'){const input=document.querySelector('#cleanup-form textarea');input.value=b.dataset.query;life.cleanupQuery=input.value;return true;}
  if(name==='cleanup-apply'){const ids=[...document.querySelectorAll('[name=cleanup-id]:checked')].map(e=>e.value);if(!ids.length)throw Error('Select at least one message.');b.disabled=true;try{const operation=document.querySelector('#cleanup-operation').value,p=await post('inbox/cleanup',{stage:'preview',messageIds:ids,operation});await post('inbox/cleanup',{stage:'apply',previewToken:p.previewToken});if(operation==='read'){life.emails=life.emails.map(e=>ids.includes(e.id)?{...e,unread:false}:e);}else life.emails=life.emails.filter(e=>!ids.includes(e.id));closeSheet(true);toast('Selected mail updated in Gmail. Refreshing the scan.');await sync();}catch(e){document.querySelector('#cleanup-error').textContent=e.message;}finally{b.disabled=false;}return true;}
  if(name==='ai-setup'){life.status=await api('status');aiSetupForm();return true;}
  if(name==='ai-test'){b.disabled=true;try{await post('ai/test',{});life.aiError='';life.status=await api('status');toast('AI connection verified. GPT-OSS 120B answered.');render();}catch(e){life.aiError=e.message;render();toast(e.message);}finally{b.disabled=false;}return true;}
  if(name==='ai-disconnect'){if(life.aiBusy||life.busy)throw Error('Wait for the current request to finish.');await api('ai/setup',{method:'DELETE'});life.status=await api('status');life.aiError='';render();toast('AI disconnected. Your diary and drafts are kept.');return true;}
  if(name==='chatgpt'){chatGPTHandoff();return true;}if(name==='copy-handoff'){await navigator.clipboard.writeText(document.querySelector('#handoff-prompt').value);toast('Prompt copied. Paste into ChatGPT.');return true;}
  if(name==='prompt'){life.draft=b.dataset.prompt;render();document.querySelector('#assistant-message')?.focus();return true;}
  if(name==='proposal-dismiss'){if(life.busy||life.aiBusy)return true;life.proposal=null;life.pendingActions=[];render();return true;}
  if(name==='proposal-save'){
   const proposal=life.proposal;if(!proposal||life.busy||life.aiBusy)return true;
   const commit=async()=>{life.busy=true;try{await store.save(data=>proposal.apply(data),'Log in-app health check-in');life.proposal=null;life.pendingActions=[];life.draft='';const total=totals(dayFor(store.data,proposal.date));life.chat.push({role:'assistant',text:`Saved and verified in your diary for ${proposal.date}. Known daily totals: ${num(total.kcal)} kcal · ${num(total.protein)} g protein · ${num(total.carbs)} g carbs · ${num(total.fat)} g fat. Estimates and incomplete entries stay labelled.`});}finally{life.busy=false;}};
   if(store.connected){try{render();await commit();toast('Saved and verified in your diary.');}catch(e){life.chat.push({role:'assistant',text:e.message});}render();return true;}
   openSheet('Connect once to save your diary',`<form><p class="help">Your food and nutrition are already filled in. Connect browser editing to save this check-in for ${proposal.date}. Saved records stay intact.</p>${saveFooter('Connect & save to diary')}</form>`,()=>wireForm(commit));return true;
  }
  return false;
 }
 document.addEventListener('submit',async e=>{if(e.target.id==='assistant-form'||e.target.id==='cleanup-form'){e.preventDefault();try{if(e.target.id==='assistant-form')await send(e.target);else await cleanup(new FormData(e.target).get('query'));}catch(err){toast(err.message);}}});
 document.addEventListener('input',e=>{if(e.target.id==='assistant-message')life.draft=e.target.value;});
 return {life,load,action,estimateFood,healthTabs,wellbeingCard,setupBlock,view(view){return view==='dashboard'?overview():view==='inbox'?inbox():view==='life'?lifeView():view==='ask'?ask():view==='insights'?insights():null;}};
}
